from abc import ABCMeta, abstractmethod
import six
import logging
from .dependency_node import DependencyNode
from taf.internal.core import Group, GroupError

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@six.add_metaclass(ABCMeta)
class ManagedComponent(object):
    """
    An object, that can be set up and torn down.

    A managed component can either be a single managed object
    or a group of managed components.
    """

    @abstractmethod
    def setup(self, group=None):
        pass

    @abstractmethod
    def teardown(self, group=None, force=False):
        pass


class ManagedObject(ManagedComponent, DependencyNode):
    """
    Managed object in a setup hierarchy.

    Methods:

    - :meth:`setup`: setup the current managed object and all its prerequisites recursively
    - :meth:`teardown`: teardown the current managed object and its prerequisites recursively

    Attributes:

    - :attr:`is_up`: returns True, if this managed object has been set up successfully

    Usage example:

        >>> from taf.internal.managedobject import ManagedObject
        >>> sequence = []
        >>> class MyManagedObject(ManagedObject):
        ...     def __init__(self, x, **kwargs):
        ...         super(MyManagedObject, self).__init__(**kwargs)
        ...         self.x = x
        ...     def _setup(self):
        ...         sequence.append("setup %s" % self.x)
        ...     def _teardown(self):
        ...         sequence.append("teardown %s" % self.x)

        >>> current = MyManagedObject("current")
        >>> prerequisite1 = MyManagedObject("prerequisite1")
        >>> prerequisite2 = MyManagedObject("prerequisite2")

        >>> current.add_prerequisite(prerequisite1)
        >>> current.add_prerequisite(prerequisite2)

        >>> current.setup()
        >>> (current.is_up, prerequisite1.is_up, prerequisite2.is_up)
        (True, True, True)

        >>> current.teardown()
        >>> (current.is_up, prerequisite1.is_up, prerequisite2.is_up)
        (False, False, False)

        >>> with MyManagedObject("contextmanager") as obj:
        ...    assert obj.is_up

        >>> set(sequence[0:2]) == set(["setup prerequisite1", "setup prerequisite2"])
        True
        >>> sequence[2] == "setup current"
        True
        >>> sequence[3] == "teardown current"
        True
        >>> set(sequence[4:6]) == set(["teardown prerequisite1", "teardown prerequisite2"])
        True
        >>> sequence[6] == "setup contextmanager"
        True
        >>> sequence[7] == "teardown contextmanager"
        True
    """

    def __init__(self, **kwargs):
        """
        Create a ManagedObject object.
        """
        super(ManagedObject, self).__init__(**kwargs)
        self._group = None

    def __enter__(self):
        self.setup()
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.teardown()

    @property
    def is_up(self):
        """
        Returns True, if this managed object has been set up successfully.
        """
        return self._group is not None

    def setup(self, group=None):
        """
        Setup the current managed object and all its prerequisites recursively.

        Setup occurs top-down.

        If a managed object is visited, which has already been set up as part
        of another or the same managed object group, then its setup will be
        skipped.

        By this marking of managed objects it is possible to first set up
        lower layer managed objects from a testsuite setup and later
        setup up and tear down higher layer managed objects from each
        test case keeping the lower layer managed objects untouched.
        Herefore the testsuite setup will call setup() for the lower layer
        managed objects with a different group argument than the testcases do
        for the higher layer managed objects.

        Setup of the prerequisites is executed in sequence (although parallel
        execution would be possible from dependency point of view).

        :param str group:
            group name for hierarchical setup (default: "default group")
        :raises Exception:
            if any prerequisite setup raises an exception
        """
        if group is None:
            group = "default group"
        if self._group is not None:
            return
        for prerequisite in self.prerequisites:
            prerequisite.setup(group=group)
        self._setup()
        self._group = group

    def teardown(self, group=None, force=False):
        """
        Teardown the current managed object and its prerequisites recursively.

        Teardown occurs bottom-up.

        If a managed object is visited, which is not marked anymore by a
        group name, because it has already been torn down as part of another
        or the same managed object group, then its teardown will be skipped.

        By this marking of managed objects it is possible to tear down
        higher layer managed objects from a testcase teardown leaving the
        lower layer managed objects untouched and later tear down lower layer
        managed objects from a testsuite teardown.
        Herefore the testcase teardown will call teardown() for the higher
        layer managed objects with a different group argument than the
        testsuite does for the lower layer managed objects.

        Teardown of the prerequisites is executed in sequence (although
        parallel execution would be possible from dependency point of view).

        By default a managed object, which still has dependers, that are up,
        cannot be torn down. First the dependers need to be torn down. This
        behaviour can be changed using force flag.

        :param str group:
            group name for hierarchical teardown (default: "default group")
        :param bool force:
            if True, execute teardown irrespective of dependers state
        :raises Exception:
            if any prerequisite teardown raises an exception
        """
        if group is None:
            group = "default group"
        if self._group is None or self._group != group:
            return
        up_dependers = [
            depender
            for depender in self.dependers
            if depender.is_up]
        if len(up_dependers) > 0:
            logger.debug(
                "dependers in state up: %s" % repr(up_dependers))
            if not force:
                return
            logger.debug("Force flag is set. Executing teardown.")
        self._teardown()
        self._group = None
        for prerequisite in self.prerequisites:
            prerequisite.teardown(group=group)

    def _setup(self):
        """
        Setup the current managed object.

        This method should be overidden in a subclass.
        """

    def _teardown(self):
        """
        Teardown the current managed object.

        This method should be overidden in a subclass.
        """


class ManagedGroup(ManagedComponent, Group):
    """
    Group of managed components.
    """

    def setup(self, group=None):
        for member in self._members:
            member.setup(group=group)

    def teardown(self, group=None, force=False):
        group_exceptions = {}
        for member in self._members:
            try:
                member.teardown(group=group, force=force)
            except Exception as e:
                logger.debug(f"teardown operation failed for member {member!r} due to exception: {e!r}")
                group_exceptions[member] = e
        if group_exceptions:
            raise GroupError(errors=group_exceptions)
